def source(asset,period,lo,hi):
 p=next((D/'resources'/asset).glob('*Displacement.png'));a=np.asarray(Image.open(p),dtype=np.float32);a=(a-a.mean())/max(float(a.std()),1e-8);a=gaussian_filter(a,lo,mode='wrap')-gaussian_filter(a,hi,mode='wrap');u=((X+.036*np.sin(X*8+Y*17))/period%1)*(a.shape[1]-1);v=((Y+.022*np.sin(X*5))/period%1)*(a.shape[0]-1);b=map_coordinates(a,[v,u],order=1,mode='wrap');return b/max(float(b.std()),1e-8)
formed=source('Metal055A',1.65,3,32);pitted=source('Metal025',2.1,3.5,24);patch=gaussian_filter(rng.standard_normal((h,w)).astype(np.float32),(8,60));patch=(patch-patch.mean())/max(float(patch.std()),1e-8);quiet=np.clip(.55+.25*patch,.18,1);medium=np.clip(.00062*formed+.00052*pitted,-.0027,.0027)*quiet;coarse=.24*old['hammer'];fine=old['fine']*.14*quiet;full=coarse+medium+fine;wear=np.load(D/'surface03/fields.npz')['wear']
